// The locked-down child process that runs a model's scene code for the judge. Started by sim.mjs with Node's
// permission model (read access to this file, world.mjs, task.mjs, three and the scene only; no writes, no child
// processes, no workers) and an empty environment. It never receives a seed, a trial number or the bumps: only the
// time and the marble's position and velocity, 60 times a second. Speaks JSON lines on stdin/stdout.
import * as THREE from 'three';
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { createInterface } from 'node:readline';
import { describeScene, checkSource, pose, SceneError } from './world.mjs';

const file = process.argv[2];
let build = null, paths = null;
const send = (o) => process.stdout.write(JSON.stringify(o) + '\n');
for await (const line of createInterface({ input: process.stdin })) {
  let m;
  try { m = JSON.parse(line); } catch { send({ error: 'bad request' }); continue; }
  try {
    if (m.op === 'describe') {
      if (!build) {
        checkSource(readFileSync(file, 'utf8'));
        build = (await import(pathToFileURL(file).href)).default;
        if (typeof build !== 'function') throw new SceneError('scene must export a default build function');
      }
      const r = describeScene({ THREE, build });
      paths = r.paths;
      send({ desc: r.desc });
    } else if (m.op === 'tick') {
      send({ poses: paths.map((p) => pose(p, m.t, m.marble)) });
    } else send({ error: 'unknown op' });
  } catch (e) {
    send({ error: String((e && e.message) || e), scene: e instanceof SceneError });
  }
}

// Browser viewer: rebuilds the scene, re-runs the same trial the judge ran, and renders it.
// URL: /harness/view.html?scene=/scenes/x.js&seed=1&cam=overview | cam=az,el,dist &t=end|seconds &play=1 &w=1280&h=720
import * as THREE from 'three';
import * as CANNON from 'cannon-es';
import { TASK, VAL_CAMERAS } from './task.mjs';
import { checkSource, describeScene, pose } from './world.mjs';
import { runTrial } from './trialrun.mjs';

const q = new URLSearchParams(location.search);
const W = +(q.get('w') || 1280), H = +(q.get('h') || 720);

export function cameraFor(spec) {
  const named = VAL_CAMERAS.find((c) => c.name === spec);
  if (named) return named;
  const [az, el, dist] = String(spec).split(',').map(Number); // degrees, degrees, metres around the desk centre
  const a = az * Math.PI / 180, e = el * Math.PI / 180;
  return { name: spec, position: [dist * Math.cos(e) * Math.sin(a), 0.2 + dist * Math.sin(e), dist * Math.cos(e) * Math.cos(a)], target: [0, 0.2, 0] };
}

async function main() {
  const sceneUrl = q.get('scene');
  const src = await (await fetch(sceneUrl, { cache: 'no-store' })).text();
  checkSource(src);
  const build = (await import(sceneUrl + '?v=' + Date.now())).default;
  const seed = +(q.get('seed') || 1);
  const bumps = q.get('bump') ? [].concat(JSON.parse(q.get('bump'))) : null;
  // In the viewer the scene's own paddle functions answer directly; the judge runs the same loop with the scene
  // locked in a separate process instead.
  const { desc, paths, decor } = describeScene({ THREE, build, keepDecor: true });
  const host = { tick: async (t, m) => paths.map((p) => pose(p, t, m)) };
  const { result, track, world } = await runTrial({ THREE, CANNON, desc, decor, host, seed, graphics: true, record: true, bumpsOverride: bumps });
  window.__result = result;

  const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
  renderer.setSize(W, H); renderer.setPixelRatio(1);
  renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  document.body.appendChild(renderer.domElement);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#f3f1ec');
  scene.add(new THREE.HemisphereLight('#ffffff', '#c8b89a', 1.6));
  const sun = new THREE.DirectionalLight('#fff4e0', 2.2);
  sun.position.set(1.2, 2.5, 1.0); sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048); Object.assign(sun.shadow.camera, { left: -1.5, right: 1.5, top: 1.5, bottom: -1.5 });
  scene.add(sun);
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(8, 8), new THREE.MeshStandardMaterial({ color: '#dcd6cc' }));
  floor.rotation.x = -Math.PI / 2; floor.position.y = -0.75; floor.receiveShadow = true; scene.add(floor);
  scene.add(world.root);

  if (q.get('trail')) {
    const pts = track.map((s) => new THREE.Vector3(...s.p));
    const trail = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), Math.max(8, pts.length * 2), 0.004, 6, false),
      new THREE.MeshBasicMaterial({ color: result.success ? '#1f9d55' : '#d64545' }));
    scene.add(trail);
  }
  const cam = cameraFor(q.get('cam') || 'overview');
  const camera = new THREE.PerspectiveCamera(45, W / H, 0.01, 50);
  camera.position.set(...cam.position); camera.lookAt(new THREE.Vector3(...cam.target));

  const apply = (k) => {
    const s = track[Math.max(0, Math.min(track.length - 1, k))];
    world.marbleMesh.position.set(...s.p); world.marbleMesh.quaternion.set(...s.q);
    world.movers.forEach((m, i) => { if (m.mesh && s.movers[i]) { m.mesh.position.set(...s.movers[i].p); m.mesh.quaternion.set(...s.movers[i].q); } });
  };
  if (q.get('play')) {
    const t0 = performance.now();
    const tick = () => {
      const t = (performance.now() - t0) / 1000;
      const k = track.findIndex((s) => s.t >= t);
      apply(k < 0 ? track.length - 1 : k);
      renderer.render(scene, camera);
      if (k < 0 && t > track[track.length - 1].t + 0.8) { window.__done = true; return; }
      requestAnimationFrame(tick);
    };
    tick();
  } else {
    const at = q.get('t');
    const k = !at || at === 'end' ? track.length - 1 : track.findIndex((s) => s.t >= +at);
    apply(k < 0 ? track.length - 1 : k);
    renderer.render(scene, camera);
  }
  window.__ready = true;
}
main().catch((e) => { window.__error = String(e && e.message || e); document.body.textContent = 'ERROR: ' + window.__error; });

#!/usr/bin/env node
// Renders a scene in headless Chromium: still screenshots from camera angles, optionally a replay video.
// node shoot.mjs <scene.js> --out dir [--seed 1] [--cams overview,closeup,low,top | "az,el,dist;..."] [--t end] [--trail] [--video]
import { createServer } from 'node:http';
import { readFile, mkdir, rename } from 'node:fs/promises';
import { resolve, relative, extname, join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
const opt = (n, d) => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : d; };
const scene = resolve(args[0]);
const out = resolve(opt('--out', 'shots'));
const seed = opt('--seed', '1');
const cams = (opt('--cams', 'overview,closeup,low,top')).split(/[;|]/).flatMap((c) => (c.includes(',') && c.split(',').length === 3 ? [c] : c.split(',')));
const at = opt('--t', 'end');
const bump = opt('--bump', '');
const W = +opt('--w', 1280), H = +opt('--h', 720);

const TYPES = { '.html': 'text/html', '.mjs': 'text/javascript', '.js': 'text/javascript', '.json': 'application/json' };
// Serve the repository root plus the scene file itself under /scene/<name>, wherever it lives.
const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  try {
    const file = url.pathname.startsWith('/scene/') ? scene : join(ROOT, decodeURIComponent(url.pathname));
    if (!file.startsWith(ROOT) && file !== scene) throw new Error('outside root');
    const body = await readFile(file);
    res.writeHead(200, { 'content-type': TYPES[extname(file)] || 'application/octet-stream', 'cache-control': 'no-store' });
    res.end(body);
  } catch { res.writeHead(404); res.end(); }
}).listen(0, '127.0.0.1');
await new Promise((r) => server.on('listening', r));
const base = `http://127.0.0.1:${server.address().port}/harness/view.html`;
const sceneParam = '/scene/' + encodeURIComponent(relative(ROOT, scene).replace(/[\\/]/g, '_'));

const browser = await chromium.launch({ args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'] });
await mkdir(out, { recursive: true });
const report = { scene: args[0], seed: +seed, shots: [] };
const trail = args.includes('--trail') ? { trail: 1 } : {};
const qs = (extra) => new URLSearchParams({ scene: sceneParam, seed, w: W, h: H, ...trail, ...(bump ? { bump } : {}), ...extra }).toString();
const waitReady = async (page, flag) => {
  await page.waitForFunction((f) => window[f] || window.__error, flag, { timeout: 180000 });
  const err = await page.evaluate(() => window.__error);
  if (err) throw new Error(err);
};
try {
  const page = await browser.newPage({ viewport: { width: W, height: H } });
  for (const cam of cams) {
    await page.goto(`${base}?${qs({ cam, t: at })}`);
    await waitReady(page, '__ready');
    const name = cam.replace(/[^a-z0-9]+/gi, '_');
    const file = join(out, `${name}.png`);
    await page.screenshot({ path: file });
    report.shots.push({ cam, file: relative(process.cwd(), file) });
    report.result = await page.evaluate(() => window.__result);
  }
  await page.close();
  if (args.includes('--video')) {
    const ctx = await browser.newContext({ viewport: { width: W, height: H }, recordVideo: { dir: out, size: { width: W, height: H } } });
    const vp = await ctx.newPage();
    await vp.goto(`${base}?${qs({ cam: cams[0], play: 1 })}`);
    await waitReady(vp, '__done');
    const v = vp.video();
    await ctx.close();
    const file = join(out, `replay_seed${seed}.webm`);
    await rename(await v.path(), file);
    report.video = relative(process.cwd(), file);
  }
} finally {
  await browser.close();
  server.close();
}
console.log(JSON.stringify(report));

