export default function build({ THREE, add, task }) {
  // Helper to place a box given its start and end points along local X,
  // with local Z horizontal and local Y pointing "up" perpendicular to X and Z.
  function makeBasis(p1, p2) {
    const a = new THREE.Vector3(...p1);
    const b = new THREE.Vector3(...p2);
    const d = new THREE.Vector3().subVectors(b, a);
    const len = d.length();
    const u = d.clone().normalize();
    const up = new THREE.Vector3(0, 1, 0);
    // w is horizontal right-hand sideways vector: u x up
    const w = new THREE.Vector3().crossVectors(u, up).normalize();
    // v is perpendicular upward normal to ramp: w x u
    const v = new THREE.Vector3().crossVectors(w, u).normalize();
    const mat = new THREE.Matrix4().makeBasis(u, v, w);
    const euler = new THREE.Euler().setFromRotationMatrix(mat, 'XYZ');
    const mid = new THREE.Vector3().addVectors(a, b).multiplyScalar(0.5);
    return { a, b, mid, len, u, v, w, rot: [euler.x, euler.y, euler.z] };
  }

  // Waypoints:
  // Behind start -> center height 0.36 -> cup rim
  const P0 = [-0.95, 0.68, -0.34];
  const P1 = [0.0, 0.36, 0.0];
  // Cup center is [0.8, 0, 0.3], innerRadius 0.07, wallHeight 0.06
  // Direction from P1 to cup center is [0.8, 0, 0.3] / 0.8544 = [0.9363, 0, 0.3511]
  // Front inner rim is at distance 0.8544 - 0.07 = 0.7844 -> [0.7345, 0.062, 0.2754]
  const P2 = [0.735, 0.062, 0.275];

  const seg1 = makeBasis(P0, P1);
  const seg2 = makeBasis(P1, P2);

  const thick = 0.012;
  const channelGap = 0.084; // inner distance between walls
  const floorWidth = 0.040; // since marble radius is 0.025, 0.084 - 0.050 = 0.034 < 0.040
  const wallHeight = 0.076;

  // 1. Upper ramp floor
  {
    const pos = seg1.mid.clone().addScaledVector(seg1.v, -thick / 2);
    add.box({
      size: [seg1.len + 0.01, thick, floorWidth],
      position: [pos.x, pos.y, pos.z],
      rotation: seg1.rot,
      color: '#d9b38c',
    });
  }

  // 2. Lower ramp floor
  {
    const pos = seg2.mid.clone().addScaledVector(seg2.v, -thick / 2);
    add.box({
      size: [seg2.len + 0.01, thick, floorWidth],
      position: [pos.x, pos.y, pos.z],
      rotation: seg2.rot,
      color: '#d9b38c',
    });
  }

  // 3 & 4. Upper ramp walls (left and right)
  for (const side of [-1, 1]) {
    const pos = seg1.mid.clone()
      .addScaledVector(seg1.v, wallHeight / 2 - 0.004)
      .addScaledVector(seg1.w, side * (channelGap / 2 + thick / 2));
    add.box({
      size: [seg1.len + 0.02, wallHeight, thick],
      position: [pos.x, pos.y, pos.z],
      rotation: seg1.rot,
      color: '#c49a6c',
    });
  }

  // 5 & 6. Lower ramp walls (left and right), extending slightly past P2 alongside cup
  const extCup = 0.07; // extend 7cm past front rim alongside the cup
  const seg2WallLen = seg2.len + extCup;
  for (const side of [-1, 1]) {
    const pos = seg2.mid.clone()
      .addScaledVector(seg2.u, extCup / 2)
      .addScaledVector(seg2.v, wallHeight / 2 - 0.004)
      .addScaledVector(seg2.w, side * (channelGap / 2 + thick / 2));
    add.box({
      size: [seg2WallLen, wallHeight, thick],
      position: [pos.x, pos.y, pos.z],
      rotation: seg2.rot,
      color: '#c49a6c',
    });
  }

  // 7 & 8. Funnel walls behind cup (V-shape around the back of the cup)
  // Cup center is [0.8, 0, 0.3]. Let's use horizontal basis (uH, wH) from seg2:
  const uH = new THREE.Vector3(seg2.u.x, 0, seg2.u.z).normalize();
  const wH = new THREE.Vector3(seg2.w.x, 0, seg2.w.z).normalize();
  const cupC = new THREE.Vector3(0.8, 0, 0.3);

  // Back apex of funnel is just behind the back inner rim of the cup (u = +0.072)
  // and the wings flare out forward to meet the extended ramp side walls around u = -0.02, w = +/- 0.08
  const funnelH = 0.16;
  const funnelY = 0.05 + funnelH / 2; // from y=0.05 to y=0.21
  const apex = cupC.clone().addScaledVector(uH, 0.078);
  for (const side of [-1, 1]) {
    const wing = cupC.clone()
      .addScaledVector(uH, -0.025)
      .addScaledVector(wH, side * 0.075);
    const dir = new THREE.Vector3().subVectors(apex, wing);
    const fLen = dir.length() + 0.015;
    const fMid = new THREE.Vector3().addVectors(wing, apex).multiplyScalar(0.5);
    const yaw = Math.atan2(-dir.z, dir.x);
    add.box({
      size: [fLen, funnelH, thick],
      position: [fMid.x, funnelY, fMid.z],
      rotation: [0, yaw, 0],
      color: '#8c6239',
    });
  }
}

